INSERT INTO content_items (id, slug, type, title_zh, summary_zh, status, visibility, release_channel, sensitivity, requires_human_review, source_ids_json, related_entity_json) VALUES ('fact_card_history_japanese_classification_pinuyumayan', 'facts/history_japanese_classification_pinuyumayan', 'verified_fact_card', '歷史分類：公開資料指出，十九世紀末進入日本殖民', '公開資料指出，十九世紀末進入日本殖民統治時期後，卑南族在民族文化分類上被稱為 Pinuyumayan，並因主要有八個部落而被稱為「八社蕃」；平台只能將「八社」作歷史用語，不可作正式分類。', 'verified_sensitive_summary', 'public_summary_only', 'preview', 'medium', 1, '["cip_puyuma_profile"]', '{"type": "fact", "id": "history_japanese_classification_pinuyumayan"}') ON DUPLICATE KEY UPDATE title_zh=VALUES(title_zh), summary_zh=VALUES(summary_zh), status=VALUES(status), visibility=VALUES(visibility), release_channel=VALUES(release_channel), sensitivity=VALUES(sensitivity), source_ids_json=VALUES(source_ids_json), related_entity_json=VALUES(related_entity_json);
INSERT INTO content_item_sections (content_item_id, sort_order, heading, body_zh, items_json) VALUES ('fact_card_history_japanese_classification_pinuyumayan', 0, '事實摘要', '公開資料指出，十九世紀末進入日本殖民統治時期後，卑南族在民族文化分類上被稱為 Pinuyumayan，並因主要有八個部落而被稱為「八社蕃」；平台只能將「八社」作歷史用語，不可作正式分類。', '[]');
INSERT INTO content_items (id, slug, type, title_zh, summary_zh, status, visibility, release_channel, sensitivity, requires_human_review, source_ids_json, related_entity_json) VALUES ('fact_card_migration_hengchun_sukaro_public', 'facts/migration_hengchun_sukaro_public', 'verified_fact_card', '歷史遷徙：公開資料指出，十八世紀有一部分卑南族', '公開資料指出，十八世紀有一部分卑南族氏族遷居恆春半島並發展出稱為「斯卡羅」（sukaro）的歷史脈絡；此主題涉及跨族群歷史，平台應以來源摘要呈現並標記待專題審核。', 'verified_sensitive_summary', 'public_summary_only', 'preview', 'medium', 1, '["cip_puyuma_profile"]', '{"type": "fact", "id": "migration_hengchun_sukaro_public"}') ON DUPLICATE KEY UPDATE title_zh=VALUES(title_zh), summary_zh=VALUES(summary_zh), status=VALUES(status), visibility=VALUES(visibility), release_channel=VALUES(release_channel), sensitivity=VALUES(sensitivity), source_ids_json=VALUES(source_ids_json), related_entity_json=VALUES(related_entity_json);
INSERT INTO content_item_sections (content_item_id, sort_order, heading, body_zh, items_json) VALUES ('fact_card_migration_hengchun_sukaro_public', 0, '事實摘要', '公開資料指出，十八世紀有一部分卑南族氏族遷居恆春半島並發展出稱為「斯卡羅」（sukaro）的歷史脈絡；此主題涉及跨族群歷史，平台應以來源摘要呈現並標記待專題審核。', '[]');
INSERT INTO content_items (id, slug, type, title_zh, summary_zh, status, visibility, release_channel, sensitivity, requires_human_review, source_ids_json, related_entity_json) VALUES ('fact_card_urban_migration_modern_fields', 'facts/urban_migration_modern_fields', 'verified_fact_card', '現代發展：公開資料指出，目前有不少卑南族人離開', '公開資料指出，目前有不少卑南族人離開東部到都市發展，並活躍於各領域；平台可建立「都會族人與現代發展」內容分類，但人物條目需另行來源查證。', 'verified_public', 'public', 'public', 'low', 0, '["cip_puyuma_profile"]', '{"type": "fact", "id": "urban_migration_modern_fields"}') ON DUPLICATE KEY UPDATE title_zh=VALUES(title_zh), summary_zh=VALUES(summary_zh), status=VALUES(status), visibility=VALUES(visibility), release_channel=VALUES(release_channel), sensitivity=VALUES(sensitivity), source_ids_json=VALUES(source_ids_json), related_entity_json=VALUES(related_entity_json);
